actions.action:
def created = []
def unchanged = []
def failed = []

// allowedNets je to, z coho zobrazenie stavia ponuku tlacidla "+". Zaklada sa
// len ziadost, takze tam patri jedina siet - a len pri zobrazeni typu Case,
// task sa zalozit neda.
def ziadost = "dovolenky/dv_ziadost"
def vsetky = "processIdentifier:\"" + ziadost + "\""
def views = [
        [id: "dv_moje", name: "Žiadosti o dovolenku", type: "Case", icon: "beach_access",
         query: vsetky, nets: [ziadost], roles: [:]],
        [id: "dv_na_schvalenie", name: "Na schválenie", type: "Case", icon: "how_to_reg",
         query: vsetky + " AND taskIds:\"t_dv_rozhodnutie\"", nets: [],
         roles: ["veduci": ziadost]],
        [id: "dv_rozpisane", name: "Rozpísané a vrátené", type: "Case", icon: "edit_calendar",
         query: vsetky + " AND taskIds:\"t_dv_podanie\"", nets: [ziadost], roles: [:]],
        // Vybavene = token je v p_vybavena, teda existuje uloha t_dv_vysledok.
        // Nefiltruje sa to podla `dv_stav`, hoci by to bolo citatelnejsie:
        // dataSet polia v Elasticu spolahlivo dopytovat nevieme, `taskIds` ano.
        [id: "dv_vybavene", name: "Vybavené", type: "Case", icon: "task_alt",
         query: vsetky + " AND taskIds:\"t_dv_vysledok\"", nets: [], roles: [:]],
]

views.each { v ->
    def id = v.id as String
    try {
        def existing = menu_item(id)
        if (existing != null) {
            def current = getFilterFromMenuItem(existing)
            def currentQuery = ((current?.dataSet?."filter"?.value ?: "") as String)
            def currentNets = (current?.dataSet?."allowedNets"?.value ?: []) as List
            // allowed_roles su ulozene ako options s klucom "importId:identifikator",
            // takze sa porovnava zakodovana podoba, nie vstupna mapa.
            def currentRoles = ((existing?.dataSet?."allowed_roles"?.options ?: [:]) as Map).keySet() as Set
            def wantRoles = ((v.roles as Map).collect { k, net -> (k as String) + ":" + (net as String) }) as Set
            if (currentQuery == (v.query as String) && currentNets == (v.nets as List)
                    && currentRoles == wantRoles) {
                bez_dialogu(existing, v.nets as List)
                unchanged << id
                return
            }
            deleteMenuItem(existing)
        }
        // Sedem argumentov = varianta z EtaskActionDelegate. Poradie NIE je
        // rovnake ako pri createFilterInMenu: tu je prve id, az potom URI.
        def item = createOrUpdateMenuItem(
                id,                 // menu_item_identifier
                "dovolenky",        // URI cesta
                v.type as String,   // "Case" alebo "Task"
                v.query as String,  // dopyt
                v.icon as String,
                v.name as String,   // nazov v menu aj nazov filtra
                v.nets as List,     // allowedNets - bez toho "+" nefunguje
                v.roles as Map      // allowed_roles: importId -> identifikator siete
        )
        if (item) { created << id } else { failed << id }
        bez_dialogu(item, v.nets as List)
    } catch (Exception e) {
        failed << (id + " (" + e.getClass().simpleName + ": " + e.message + ")")
    }
}

// Vysledok patri do nazvu casu, nie do datoveho pola: po createFilterInMenu sa
// zapis do vlastneho casu neuchova - engine medzitym zakladal ine casy a nas
// outcome zahodil. changeCaseProperty prezije.
def summary = "Menu Dovoleniek – " + (created.size() + unchanged.size()) + "/" + views.size()
if (failed) {
    summary = "CHYBA menu Dovoleniek – nepodarilo sa: " + failed.join(", ")
}
changeCaseProperty("title").about { summary }

document.function:
{ def menuItem, def nets ->
    // Bez tohto vyskoci pri "+" dialóg "Vyplňte názov prípadu" a názov žiadosti
    // si vymýšľa človek. Riadi to `enable_case_title` na prechode `view` položky
    // menu - nie je to argument `createOrUpdateMenuItem`, takže sa dopisuje
    // zvlášť cez setData. Case sa potom založí rovno a názov mu dá `create`
    // akcia siete. Týka sa len zobrazení, ktoré vôbec majú allowedNets.
    if (menuItem == null || !nets) return
    setData("view", menuItem, [
            "enable_case_title"             : ["value": false, "type": "boolean"],
            "case_require_title_in_creation": ["value": false, "type": "boolean"]
    ])
}

{ def identifier ->
    // `findMenuItem(id)` z ActionDelegate existujucu polozku nenajde (hlada
    // v inom rozsahu), takze by sa pri kazdom spusteni zalozila druha sada
    // zobrazeni. Polozky su casy `preference_filter_item`, takze si ich
    // prejdeme sami.
    def id = ((identifier ?: "") as String).trim()
    if (!id) return null
    def items = findCases { it.processIdentifier.eq("preference_filter_item") }
    return items?.find { ((it.dataSet["menu_item_identifier"]?.value ?: "") as String) == id }
}
